<?php require 'app/init.php';require 'app/view.php';$u=require_user();top('Guardados');?><main class="card" style="max-width:800px;margin:30px auto"><h1>Guardados</h1><?php $s=db()->prepare('SELECT p.id,p.titulo,p.contenido,u.nombre FROM guardados g JOIN publicaciones p ON p.id=g.publicacion_id JOIN usuarios u ON u.id=p.usuario_id WHERE g.usuario_id=? ORDER BY p.creado_en DESC');$s->execute([$u['id']]);foreach($s as $p):?><div class="comment"><h3><a href="publicacion.php?id=<?=$p['id']?>"><?=e($p['titulo']?:'Publicación de '.$p['nombre'])?></a></h3><p><?=e(mb_strimwidth($p['contenido'],0,180,'…'))?></p></div><?php endforeach;?></main><?php bottom();?>